     Figure(lambda t: table(t, [["Letters", "Sound", "Examples"], ["h", "silent", "hola, hasta"], ["j; g before e, i", "strong h", "jugo, gente, Gibraltar"], ["g before a, o, u", "g as in go", "gato, amigo"],
                                ["c before e, i; z", "s (Latin America) / th (much of Spain)", "cero, cinco, zapato"], ["c before a, o, u; qu", "k", "casa, queso"], ["ll, y", "y as in yes", "llamo, yo"],
                                ["ñ", "ny as in canyon", "señor, mañana"], ["r between vowels", "quick tap", "pero (but)"], ["rr; r at start of word", "rolled (trilled)", "perro (dog), Rosa"], ["b, v", "the same soft b", "bien, vaca"]],
                            [1.7 * inch, 2.0 * inch, 2.1 * inch], width=5.8 * inch, font_size=9)),
