L12 = Lesson("1.12", "Tú, usted, vosotros, ustedes: Regional Differences",
    "I can choose the right form of “you” and explain regional differences.", "ACTFL Cultures, Comparisons",
    [("vosotros", "you all (informal), used mainly in Spain"), ("ustedes", "you all (both informal and formal in Latin America)")],
    "Do you say “you all,” “y'all,” “you guys,” or “yous”? English has regional differences too!",
    [Text("<b>Singular:</b> use <b>tú</b> with friends, family, and peers, and <b>usted</b> with adults you don't know well and people you respect. <b>Plural:</b> in Latin America, <b>ustedes</b> is used for any group. In most of Spain, <b>vosotros</b> is used with groups of friends, and <b>ustedes</b> is formal."),
     Callout("CULTURA", "In parts of Central and South America (including Argentina, Uruguay, and much of Central America), people use <b>vos</b> instead of tú with its own verb forms (vos sos = tú eres). You don't need to use vos, but you'll hear it in songs, movies, and conversations."),
     Figure(lambda t: table(t, [["Situation", "Latin America", "Spain"], ["your best friend", "tú", "tú"], ["your friend's grandmother", "usted", "usted"], ["three classmates", "ustedes", "vosotros/as"], ["three teachers", "ustedes", "ustedes"]],
                            [2.0 * inch, 1.8 * inch, 1.8 * inch], width=5.6 * inch)),
     KeyIdea("tú/usted for one person; ustedes (Latin America) or vosotros (Spain) for informal groups; ustedes for formal groups everywhere.")],
    [Problem("Group of friends in Mexico", "ustedes"), Problem("Group of friends in Madrid", "vosotros/as"), Problem("What is vos?", "an informal you used in parts of Latin America, like Argentina")],
    [S("Calentamiento", [SA("María / México (nationality)", "María es mexicana."), SA("Where are you from? (usted)", "¿De dónde es usted?")], cols=2),
     S("Practica", [SA(q, a) for q, a in [("your cousins (Spain)", "vosotros"), ("your cousins (Colombia)", "ustedes"), ("a police officer", "usted"), ("your little sister", "tú")]], cols=2),
     S("Compara", [OR("Compare Spanish “you” forms with English regional forms (y'all, you guys).", "Answers vary; both languages vary by region and formality.", lines=3)])],
    tsp("Students choose forms of address by region and register.", "Cultures and comparisons.", "Workbook Lesson 1.12",
        "Y'all and you guys.", "Read the situations aloud.", "Regional table; vos.", "Practica; comparison.",
        ["Using vosotros in Latin American contexts."], ["Decision flowchart."], ["Listen to an Argentine song and notice vos."], speak="Role-play forms of address; tomorrow's Prueba 3.", minutes=25),
    summary="Forms of “you” vary by formality and region.")

# ================================================================= Week 4 · Numbers, age, class, world
L13 = Lesson("1.13", "Los números 0–20",
    "I can count, add, and subtract from 0 to 20.", "ACTFL Novice Mid · Interpretive",
    [("más / menos / son", "plus / minus / equals")],
    "Which numbers do you think are hardest to learn? Why?",
    [Figure(lambda t: table(t, [["0 cero", "1 uno", "2 dos", "3 tres", "4 cuatro", "5 cinco", "6 seis"], ["7 siete", "8 ocho", "9 nueve", "10 diez", "11 once", "12 doce", "13 trece"],
                                ["14 catorce", "15 quince", "16 dieciséis", "17 diecisiete", "18 dieciocho", "19 diecinueve", "20 veinte"]], [0.82 * inch] * 7, header=False, width=5.74 * inch, font_size=9.5)),
     Text("Eleven through fifteen have their own words. Sixteen through nineteen combine <b>diez y</b> (ten and) into one word: <b>dieci</b>séis, <b>dieci</b>siete. Note the accent on dieciséis."),
     Example("Math in Spanish", "¿Cuántos son ocho más siete?", ["8 + 7 = 15", "Answer: Ocho más siete son quince."], "Quince."),
     KeyIdea("Learn 11–15 as new words; 16–19 are dieci- + the ones digit.")],
    [Problem("14 =", "catorce"), Problem("diecinueve =", "19"), Problem("doce menos cinco =", "siete")],
    [S("Calentamiento", [SA("You all (Spain, friends)", "vosotros"), SA("Formal you", "usted")], cols=2),
     S("Practica", [SA(q, a) for q, a in [("once más cuatro =", "quince"), ("veinte menos tres =", "diecisiete"), ("nueve más nueve =", "dieciocho"), ("trece más tres =", "dieciséis"), ("Write 12 in Spanish.", "doce")]], cols=2),
     S("Escucha", [LISTEN("Write the numbers you hear.", "trece … dieciséis … once … veinte", "13, 16, 11, 20")])],
    tsp("Students count and compute to 20.", "Interpretive listening: numbers.", "Workbook Lesson 1.13",
        "Hardest numbers.", "Count aloud; clap patterns.", "Teen number patterns.", "Practica; dictation.",
        ["Confusing doce/dos and trece/tres."], ["Number line 0–20."], ["Bingo with numbers 0–20."], minutes=25),
    summary="Cero to veinte.")

L14 = Lesson("1.14", "Tener: Age and Phone Numbers",
    "I can ask and tell ages using tener and give a phone number.", "ACTFL Novice Mid · Interpersonal",
    [("tener", "to have"), ("tengo / tienes / tiene", "I have / you have / he, she has, you (formal) have")],
    "Spanish doesn't say “I am 12.” What does it say instead?",
    [Text("Spanish expresses age with <b>tener</b>: <b>Tengo doce años</b> (literally, “I have twelve years”). For now, learn three forms: <b>tengo</b>, <b>tienes</b>, <b>tiene</b>. You'll learn the full conjugation in Unit 3."),
     Phrases("Edad (Age)", [("¿Cuántos años tienes?", "KWAHN-tohs AH-nyohs TYEH-nehs", "How old are you?"), ("Tengo doce años.", "TEHN-goh DOH-seh AH-nyohs", "I'm 12."),
                            ("¿Cuántos años tiene tu hermano?", "TYEH-neh", "How old is your brother?"), ("Tiene ocho años.", "TYEH-neh", "He's 8.")]),
     Text("Phone numbers are usually said in pairs: 601-555-12-18 → seis, cero, uno; cinco, cinco, cinco; doce; dieciocho. <b>¿Cuál es tu número de teléfono?</b> (What's your phone number?)"),
     WatchOut("Never drop the tilde in <b>años</b> (years). Without it, the word means something completely different."),
     KeyIdea("Age uses tener: tengo, tienes, tiene ___ años.")],
    [Problem("I'm 13.", "Tengo trece años."), Problem("How old are you? (formal)", "¿Cuántos años tiene usted?"), Problem("She's 17.", "Tiene diecisiete años.")],
    [S("Calentamiento", [SA("15 =", "quince"), SA("dieciocho =", "18")], cols=2),
     S("Practica", [SA(q, a) for q, a in [("I'm 12.", "Tengo doce años."), ("Are you 14?", "¿Tienes catorce años?"), ("My cousin is 19.", "Mi primo tiene diecinueve años."), ("Fix: Soy doce años.", "Tengo doce años.")]], cols=1),
     S("Habla", [OR("Ask three people their ages (use usted for adults) and write the answers in full sentences.", "Answers vary.", lines=3)])],
    tsp("Students use tener for age.", "Interpersonal: personal information.", "Workbook Lesson 1.14",
        "I am 12 vs I have 12 years.", "Model questions; pairs practice.", "Tener forms; phone numbers.", "Practica; interviews.",
        ["Using ser for age."], ["Sentence frame cards."], ["Make a family age chart in Spanish."], minutes=25),
    summary="Tengo ___ años.")

